function ctx(){return {s,L,name,fmt,scene,renderCatalog};}
function refreshRangeContent(host,html){
  const template=document.createElement('div');template.innerHTML=html;
  const selector='.diagram,.lab-readout,.table-wrap,.linear-ruler,.metric-note,.notice';
  const roots=node=>[...node.querySelectorAll(selector)].filter(el=>!el.parentElement.closest(selector));
  const old=roots(host),fresh=roots(template);if(old.length===fresh.length)old.forEach((el,i)=>el.replaceWith(fresh[i]));
  for(const field of host.querySelectorAll('.range-field')){const input=field.querySelector('input'),next=template.querySelector('[data-field="'+CSS.escape(input.dataset.field)+'"]');if(next)field.querySelector('output').textContent=next.closest('label').querySelector('output').textContent;}
}
function renderDialog(preserve=false,finishRange=false){if(!s.tool)return;if(preserve&&!finishRange&&dialog.contains(document.activeElement)&&document.activeElement.matches('input[type=range]')){refreshRangeContent($('dialog-content'),renderTool(ctx()));return;}const scroll=$('dialog-content').scrollTop,active=document.activeElement?.dataset.field,start=document.activeElement?.selectionStart;const title=toolNames[s.tool]||[s.tool,s.tool];$('dialog-head').innerHTML=`${s.toolStack.length?IB('tool-back',L('Voltar','Back'),'back'):icon('orbit')}<div class="dialog-title-group"><div class="eyebrow">${L('OBSERVATÓRIO DO SISTEMA SOLAR','SOLAR SYSTEM OBSERVATORY')}</div><h2 id="tool-title">${L(...title)}</h2></div>${IB('close-tool',L('Voltar à exploração','Return to exploration'),'close')}`;$('dialog-content').innerHTML=renderTool(ctx())+(s.activity&&!['learn','import'].includes(s.tool)?`<div class="activity-in-dialog">${activityMarkup()}</div>`:'');$('dialog-content').scrollTop=preserve?scroll:0;if(preserve&&active){const field=$('dialog-content').querySelector(`[data-field="${CSS.escape(active)}"]`);if(field){field.focus({preventScroll:true});try{field.setSelectionRange(start,start);}catch{}}}}
const freezingTools=['compare','scale','seasons','moon','kepler','gravity','outer','frames'];
function openTool(id){if(!toolNames[id])return;if(s.photo&&id!=='capture')exitPhoto();if(s.tour)pauseTour();if(!s.tool){s.toolSaved={view:scene.snapshot(),paused:s.clock.paused,freeze:false,focus:document.activeElement};s.toolStack=[];}else if(s.tool!==id){s.toolStack.push({tool:s.tool,scroll:$('dialog-content').scrollTop,article:s.toolData.article});}
  if(freezingTools.includes(id)&&!s.toolSaved.freeze){s.toolSaved.paused=s.clock.paused;s.toolSaved.freeze=true;s.clock.paused=true;}
  if(id==='measure'){s.measurement??={...s.toolData.measure};}if(id==='time'){s.toolData.dateInput=new Date(s.clock.time).toISOString().slice(0,16);s.toolData.customRate=s.clock.speed*s.clock.direction;s.toolData.timelineAnchor=s.clock.time;s.toolData.timelineOffset=0;}if(id==='settings')s.sceneDiagnostics=scene.diagnostics();s.tool=id;renderDialog();renderActivity();if(!dialog.open)dialog.showModal();renderHeader();renderTimebar();}
function closeTool(){const saved=s.toolSaved,action=saved?.focus?.dataset.action,value=saved?.focus?.dataset.value;s.tool=null;s.toolStack=[];s.toolSaved=null;dialog.close();if(saved?.freeze)s.clock.paused=saved.paused;s.importData=null;renderAll();let target=saved?.focus;if(!target?.isConnected&&action)target=[...document.querySelectorAll(`[data-action="${CSS.escape(action)}"]${value?`[data-value="${CSS.escape(value)}"]`:''}`)].find(el=>el.offsetParent!==null);(target?.isConnected?target:$('topbar').querySelector('button'))?.focus({preventScroll:true});}
function toolBack(){if(!s.toolStack.length){closeTool();return;}const previous=s.toolStack.pop();s.tool=previous.tool;s.toolData.article=previous.article;renderDialog();$('dialog-content').scrollTop=previous.scroll;}
function selectBody(id,focus=false){if(!byId[id])return;if(byId[id].type==='region'){s.toolData.outer.step=id==='oort'?3:id==='kuiper'?1:0;openTool('outer');return;}
  if(s.measurePick){if(s.measurePick===1){s.measurement.a=id;s.measurePick=2;toast(L('Agora escolha o segundo extremo.','Now choose the second endpoint.'));}else{s.measurement.b=id;s.measurePick=0;openTool('measure');}renderStatus();return;}
  if(s.tour)pauseTour();scene.transition=null;s.selected=id;s.inspectorOpen=true;s.recent=[id,...s.recent.filter(x=>x!==id)].slice(0,12);if(!s.data.progress.visited.includes(id)){s.data.progress.visited.push(id);save();}s.navOpen=false;if(byId[id].type==='moon')scene.system=byId[id].parent;if(s.tool&&['catalog','commands'].includes(s.tool))closeTool();renderNavigator();renderInspector();renderStatus();renderActivity();updateInsets();announce(`${name(byId[id])}. ${L(...byId[id].description)}`);if(focus)scene.focus(id);}

function renderCatalog(commands=false){const d=s.toolData,q=d.commandQuery,all=searchBodies(q);let list=all.filter(b=>d.catalogFilter==='all'||d.catalogFilter==='favorites'&&s.data.favorites.includes(b.id)||b.type===d.catalogFilter);if(d.catalogSort==='diameter')list.sort((a,b)=>(b.radius||0)-(a.radius||0));if(d.catalogSort==='distance')list.sort((a,b)=>(a.a||0)-(b.a||0));const actions=[['play',L('Pausar / reproduzir o tempo','Pause / play time')],['focus',L('Focalizar seleção','Focus selection')],['labels',L('Alternar rótulos','Toggle labels')],['compare-selected',L('Abrir comparação','Open comparison')],['start-tour',L('Começar a grande viagem','Start grand tour'),'grand'],['settings',L('Abrir preferências','Open preferences')],['photo',L('Fotografar','Photograph')],['reset-view',L('Restaurar vista','Reset view')]];return `<label class="search-shell" style="margin-bottom:18px">${icon('search')}<input type="search" autofocus data-field="commandQuery" value="${e(q)}" placeholder="${L('Nome, planeta, lua ou ação…','Name, planet, moon or action…')}" aria-label="${L('Buscar objetos e ações','Search objects and actions')}"/></label>${!commands?`<div class="form-grid">${S('catalogFilter',L('Filtrar catálogo','Filter catalog'),[['all',L('Todos','All')],['planet',L('Planetas','Planets')],['moon',L('Luas','Moons')],['dwarf',L('Planetas anões','Dwarf planets')],['asteroid',L('Asteroides','Asteroids')],['region',L('Regiões educativas','Educational regions')],['favorites',L('Favoritos','Favorites')]],d.catalogFilter)}${S('catalogSort',L('Ordenar por grandeza','Sort by quantity'),[['order',L('Ordem do catálogo','Catalog order')],['diameter',L('Maior diâmetro médio','Largest mean diameter')],['distance',L('Semieixo maior crescente','Increasing semi-major axis')]],d.catalogSort)}</div>`:''}<div class="glossary-grid" style="margin-top:17px">${list.map((b,i)=>bodyRow(b,i)).join('')||`<div class="empty">${L('Nenhum resultado. Busque Terra, Earth, Saturno ou uma lua.','No results. Search Earth, Terra, Saturn or a moon.')}${B('catalog-reset',L('Limpar busca e filtros','Clear search and filters'))}</div>`}</div>${commands?`<div class="divider"></div><div class="stack">${actions.filter(([,label])=>label.toLowerCase().includes(q.toLowerCase())||!q).map(([action,label,value])=>B('command',label,{value:[action,value||''].join('|'),ico:'arrow',cls:'secondary'})).join('')}</div>`:''}<p class="metric-note">${L('Catálogo curado. Luas exibidas não representam a contagem total conhecida. Regiões são esquemáticas; Cometa Aurora é hipotético.','Curated catalog. Displayed moons are not the total known count. Regions are schematic; Comet Aurora is hypothetical.')}</p>`;}

scene=new ObservatoryScene($('scene'),$('scene-labels'),s,{name,reduced,select(ids){if(ids.length>1){s.toolData.commandQuery='';openTool('catalog');toast(L('Objetos sobrepostos. Escolha no catálogo.','Overlapping objects. Choose from the catalog.'));}else selectBody(ids[0]);},focus:id=>selectBody(id,true),manual:()=>{if(s.tour)pauseTour();},travel:()=>announce(L('Câmera posicionada.','Camera positioned.')),camera:mode=>{s.camera=mode;renderStatus();},error:kind=>{requestAnimationFrame(()=>showRecovery(kind));},recovered:()=>{$('recovery').hidden=true;},captureCaption:()=>`${name(byId[s.selected])} · ${new Date(s.clock.time).toISOString().slice(0,16)} UTC · ${s.prefs.scale==='explore'?L('Escala de exploração','Exploration scale'):L('Escala real','True scale')} · ${L('modelo aproximado','approximate model')}`});

function showRecovery(kind){$('recovery').hidden=false;$('recovery').innerHTML=kind==='webgl'?`${L('O 3D não está disponível neste navegador. Catálogo, diagramas, comparações e atividades continuam acessíveis.','3D is unavailable in this browser. Catalog, diagrams, comparisons and activities remain accessible.')} ${B('retry-renderer',L('Tentar novamente','Retry'),{cls:'secondary'})}`:`${L('O contexto gráfico foi interrompido. Seus dados estão preservados. Aguardando recuperação do navegador.','Graphics context was interrupted. Your data is preserved. Waiting for browser recovery.')} ${B('retry-renderer',L('Recarregar vista','Reload view'),{cls:'secondary'})}`;if(kind==='webgl'){$('scene').innerHTML=`<div class="fallback-explorer"><div class="eyebrow">${L('EXPLORADOR EM DIAGRAMAS','DIAGRAM EXPLORER')}</div><h2>${L('Os mundos continuam aqui.','The worlds are still here.')}</h2><p>${L('Selecione um objeto para ler e comparar. Os laboratórios funcionam sem aceleração 3D.','Select an object to read and compare. Laboratories work without 3D acceleration.')}</p><svg viewBox="0 0 620 260" role="img" aria-label="${L('Sistema Solar esquemático','Schematic Solar System')}">${planets.map((b,i)=>`<circle cx="${60+i*73}" cy="125" r="${7+Math.sqrt(b.radius/6371)*10}" fill="${b.color}"/><text x="${60+i*73}" y="195" text-anchor="middle" fill="#e2e9ee" font-size="10">${name(b)}</text>`).join('')}</svg>${B('open',L('Explorar o catálogo','Explore the catalog'),{value:'catalog',cls:'primary'})}</div>`;}}

function startTour(id){if(s.tool)closeTool();if(s.tour)exitTour();s.activity=null;s.welcome=false;const tr=tours.find(x=>x.id===id)||tours[0];s.tour={id:tr.id,index:0,paused:false,auto:false,elapsed:0,visited:[],stopList:false,narration:false,saved:{view:scene.snapshot(),selected:s.selected,paused:s.clock.paused,speed:s.clock.speed,direction:s.clock.direction,labels:s.prefs.labels,orbits:s.prefs.orbits}};s.clock.speed=3600;s.clock.direction=1;s.clock.paused=reduced();s.prefs.labels='system';s.prefs.orbits='system';visitStop();renderAll();}
function visitStop(){const t=s.tour;if(!t)return;const tr=tours.find(x=>x.id===t.id),id=tr.stops[t.index];s.selected=id;s.inspectorOpen=false;t.elapsed=0;const mode=byId[id].type==='planet'&&children(id).length&&t.id==='giants'?'system':'focus';scene.focus(id,mode,'default');if(t.narration)speakStop();renderTour();renderNavigator();renderInspector();renderStatus();updateInsets();}
function stopText(){const t=s.tour,tr=tours.find(x=>x.id===t?.id),b=byId[tr?.stops[t?.index]];if(!b)return '';if(t.id==='light'){const seconds=distanceAt('sun',b.id,s.clock.time).seconds;return `${L(...b.description)} ${L('Tempo da luz até o Sol neste modelo','Light-time to the Sun in this model')}: ${fmt(seconds,1)} s.`;}if(t.id==='scale')return `${L(...b.description)} ${L('Diâmetro relativo à Terra','Diameter relative to Earth')}: ${fmt(b.radius/byId.earth.radius,3)}×. ${L('Abra o laboratório para comparar sem exagero de tamanho.','Open the laboratory to compare without size exaggeration.')}`;return L(...b.description);}
function pauseTour(){if(!s.tour)return;s.tour.paused=true;window.speechSynthesis?.cancel();scene.transition=null;renderTour();}
function resumeTour(){if(!s.tour)return;s.tour.paused=false;scene.focus(tours.find(x=>x.id===s.tour.id).stops[s.tour.index]);if(s.tour.narration)speakStop();renderTour();}
function exitTour(){if(!s.tour)return;const saved=s.tour.saved;window.speechSynthesis?.cancel();s.tour=null;s.prefs.labels=saved.labels;s.prefs.orbits=saved.orbits;s.clock.speed=saved.speed;s.clock.direction=saved.direction;s.clock.paused=saved.paused;s.selected=saved.selected;scene.restore(saved.view);s.inspectorOpen=true;renderAll();}
function tourNext(delta){const t=s.tour;if(!t)return;const tr=tours.find(x=>x.id===t.id);if(t.elapsed>=1&&!t.visited.includes(t.index))t.visited.push(t.index);const next=t.index+delta;if(next>=tr.stops.length){if(t.visited.length>=Math.ceil(tr.stops.length*.7)&&!s.data.progress.tours.includes(t.id)){s.data.progress.tours.push(t.id);save();}exitTour();openTool('learn');toast(L('Viagem encerrada. Escolha uma atividade para continuar descobrindo.','Journey finished. Choose an activity to keep discovering.'));return;}t.index=clamp(next,0,tr.stops.length-1);visitStop();}
function speakStop(){if(!s.tour||!('speechSynthesis'in window)||!s.prefs.sound)return;window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(stopText());utterance.lang=s.prefs.language==='en'?'en-US':'pt-BR';utterance.onerror=()=>toast(L('A voz não ficou disponível. O texto completo continua na tela.','Voice was unavailable. The full text remains on screen.'));window.speechSynthesis.speak(utterance);}
function renderTour(){const el=$('tourbar');el.hidden=!s.tour||!!s.tool||!!s.photo;if(!s.tour)return;const t=s.tour,tr=tours.find(x=>x.id===t.id),b=byId[tr.stops[t.index]];el.innerHTML=`<div class="tour-progress"><span style="width:${(t.index+1)/tr.stops.length*100}%"></span></div><div class="tour-kicker"><span class="eyebrow">${L(...tr.title)} · ${t.index+1} / ${tr.stops.length}</span>${IB('tour-exit',L('Sair do passeio','Exit tour'),'close')}</div><h3>${name(b)}</h3><p>${stopText()}</p><div class="tour-controls">${B('tour-prev',L('Anterior','Previous'),{ico:'back',disabled:t.index===0})}${B('tour-toggle',t.paused?L('Retomar','Resume'):L('Pausar','Pause'),{ico:t.paused?'play':'pause',cls:'secondary'})}${B('tour-next',t.index===tr.stops.length-1?L('Concluir','Finish'):L('Próxima parada','Next stop'),{ico:'next',cls:'primary'})}<span class="spacer"></span>${IB('tour-inspect',L('Inspecionar detalhe','Inspect detail'),'focus')}${IB('tour-stops',L('Lista de paradas','Stop list'),'menu')}${IB('tour-restart-stop',L('Recomeçar parada','Restart stop'),'reset')}${IB('tour-narrate',L('Ativar ou silenciar narração','Enable or mute narration'),'volume',{pressed:t.narration})}</div><div class="row" style="margin-top:8px">${K('tour.auto',L('Avançar automaticamente após a leitura','Advance automatically after reading'),t.auto)}${tr.tool?B('open',L('Investigar no laboratório','Investigate in the laboratory'),{value:tr.tool,cls:'secondary'}):''}</div>${t.stopList?`<div class="tour-stop-list">${tr.stops.map((id,i)=>B('tour-jump',`${i+1}. ${name(byId[id])}`,{value:String(i),cls:i===t.index?'primary':''})).join('')}</div>`:''}`;}
function startActivity(id){if(s.tool)closeTool();if(s.tour)exitTour();const a=activities.find(x=>x.id===id);if(!a)return;s.activity=a.id;s.activityAnswer='';s.activityFeedback='';s.activityHint=false;s.activityCollapsed=false;s.data.progress.activity=id;save();s.welcome=false;selectBody(a.body,true);s.activitySeenSources=false;renderAll();if(a.tool){if(a.id==='size')s.toolData.compare={ids:['earth','jupiter'],ref:'earth'};if(a.id==='light')s.measurement={...initialLabs().measure,time:s.clock.time};openTool(a.tool);}}
function activityMarkup(){const a=activities.find(x=>x.id===s.activity);if(!a)return '';return `<div class="tour-kicker"><span class="eyebrow amber">${L(...a.theme)} · ${activities.indexOf(a)+1} / 12</span>${IB('activity-exit',L('Sair e guardar progresso','Exit and keep progress'),'close')}</div><h3>${L(...a.title)}</h3><p>${L(...a.task)}</p>${a.choices?`<div class="answer">${a.choices.map((choice,i)=>B('activity-answer',L(...choice),{value:String(i),cls:`choice secondary ${s.activityAnswer===String(i)?'selected':''}`,pressed:s.activityAnswer===String(i)})).join('')}</div>`:['number','light'].includes(a.kind)?`<label class="field">${L('Sua resposta numérica','Your numerical answer')}<input type="text" inputmode="decimal" data-field="activityAnswer" value="${e(s.activityAnswer)}"/></label>`:''}<div class="row" style="margin-top:12px">${B('activity-check',L('Verificar descoberta','Check discovery'),{ico:'check',cls:'primary'})}${B('activity-hint',L('Uma pista','A hint'),{ico:'help',cls:'secondary'})}${a.tool?B('open',L('Abrir ferramenta','Open tool'),{value:a.tool,cls:'secondary'}):B('activity-inspect',L('Inspecionar objeto','Inspect object'),{ico:'eye',cls:'secondary'})}${s.activityFeedback==='success'?B('activity-next',L('Próxima atividade','Next activity'),{ico:'next',cls:'secondary'}):''}</div>${s.activityHint?notice(L(...a.hint)):''}${s.activityFeedback?`<div class="activity-feedback" role="status">${s.activityFeedback==='success'?`✓ ${L(...a.explanation)}`:L('Ainda não. Confira a configuração e experimente outra vez.','Not yet. Check the configuration and try again.')}</div>`:''}`;}
function renderActivity(){let resume=$('resume-activity');if(!resume){resume=document.createElement('div');resume.id='resume-activity';document.querySelector('#app').append(resume);}resume.hidden=!s.activity||!s.activityCollapsed||!!s.photo||!!s.tool;resume.innerHTML=B('activity-resume',L('Retomar descoberta','Resume discovery'),{ico:'book',cls:'primary'});$('activitybar').hidden=!s.activity||!!s.tool||!!s.photo||!!s.activityCollapsed;if(s.activity)$('activitybar').innerHTML=activityMarkup();}
function checkActivity(){const a=activities.find(x=>x.id===s.activity);let success=false;const n=Number(s.activityAnswer.replace(',','.'));if(a.kind==='selected')success=s.selected===a.answer;else if(a.kind==='phase')success=lunarPhase(s.toolData.moon.angle).fraction>=.99;else if(a.kind==='seasons')success=s.toolData.seasons.tilt===0&&s.toolData.seasons.latitude===45;else if(a.kind==='number')success=s.activityAnswer.trim()!==''&&Number.isFinite(n)&&n>=a.range[0]&&n<=a.range[1]&&(a.id!=='gravity'||s.toolData.gravityBody==='moon'&&s.toolData.personMass===70)&&(a.id!=='scale'||s.toolData.scale.ref==='earth'&&s.toolData.scale.size===1&&s.toolData.scale.unit==='cm');else if(a.kind==='light'){const m=s.measurement;success=s.activityAnswer.trim()!==''&&m&&[m.a,m.b].includes('earth')&&[m.a,m.b].includes('moon')&&Math.abs(n-distanceAt(m.a,m.b,m.frozen?m.time:s.clock.time).seconds)<.12;}else{success=s.activityAnswer===String(a.answer);if(a.id==='size')success&&=s.toolData.compare.ref==='jupiter'&&s.toolData.compare.ids.includes('earth');if(a.id==='speed')success&&=s.toolData.kepler.e>=.5;if(a.id==='rings')success&&=scene.targetId==='saturn'&&scene.mode!=='overview';if(a.id==='uncertainty')success&&=s.selected==='moon'&&s.activitySeenSources;}
  s.activityFeedback=success?'success':'retry';if(success&&!s.data.progress.activities.includes(a.id)){s.data.progress.activities.push(a.id);save();}if(s.tool)renderDialog(true);else renderActivity();}
function exitActivity(){s.activity=null;s.activityAnswer='';s.activityFeedback='';renderAll();}

function enterPhoto(){if(scene.failed){toast(L('Fotografia 3D indisponível. Exporte diagramas pela comparação.','3D photography is unavailable. Export diagrams from comparison.'));return;}if(s.tool)closeTool();if(s.tour)pauseTour();if(s.photo)return;s.photo={saved:{prefs:{...s.prefs},view:scene.snapshot(),paused:s.clock.paused},freeze:true,labels:false,orbits:false,guides:true,aspect:'screen',resolution:1,caption:true};s.clock.paused=true;s.prefs.labels='none';s.prefs.orbits='none';renderAll();}
function exitPhoto(){if(!s.photo)return;stopRecording();const saved=s.photo.saved;s.photo=null;s.prefs={...saved.prefs};s.clock.paused=saved.paused;scene.restore(saved.view);renderAll();}
function renderPhoto(){const p=s.photo;if(p&&$('photobar').contains(document.activeElement)&&document.activeElement.matches('input[type=range]')){const input=document.activeElement;input.closest('label').querySelector('output').textContent=input.value+(input.dataset.field==='photo.fov'?'°':'');return;}$('photobar').hidden=!p;$('photo-guides').hidden=!p?.guides;$('photo-frame').hidden=!p||p.aspect==='screen';if(!p)return;$('photobar').innerHTML=`<div class="row between"><div class="row"><span class="eyebrow amber">${L('MODO FOTOGRAFIA','PHOTO MODE')}</span><span class="small muted">${name(byId[s.selected])}</span></div><div class="row">${B('capture',L('Capturar PNG','Capture PNG'),{ico:'camera',cls:'primary'})}${B('record',s.recording?L('Parar gravação','Stop recording'):L('Gravar até 15 s','Record up to 15 s'),{ico:s.recording?'pause':'play',cls:'secondary'})}${IB('photo-exit',L('Sair da fotografia','Exit photography'),'close')}</div></div><div class="photo-controls">${R('photo.fov',L('Campo de visão','Field of view'),scene.camera.fov,20,70,1,'°')}${R('pref.exposure',L('Exposição','Exposure'),s.prefs.exposure,.3,2,.05)}${R('pref.background',L('Fundo','Background'),s.prefs.background,0,1,.05)}${S('photo.aspect',L('Proporção','Aspect ratio'),[['screen',L('Tela','Screen')],['landscape','16:9'],['square','1:1'],['portrait','3:4']],p.aspect)}${S('photo.resolution',L('Resolução','Resolution'),[[1,L('Resolução da tela','Canvas resolution')],[2,L('Até 2× · máximo 4096 px','Up to 2× · max 4096 px')]],p.resolution)}</div><div class="row">${K('photo.freeze',L('Congelar tempo','Freeze time'),p.freeze)}${K('photo.labels',L('Rótulos','Labels'),p.labels)}${K('photo.orbits',L('Órbitas','Orbits'),p.orbits)}${K('photo.guides',L('Guias','Guides'),p.guides)}${K('photo.caption',L('Legenda e créditos','Caption and credits'),p.caption)}${B('photo-preset',L('Terra no terminador','Earth at the terminator'),{value:'earth',cls:'secondary'})}${B('photo-preset',L('Acima dos anéis','Above the rings'),{value:'saturn',cls:'secondary'})}</div>`;$('photo-guides').innerHTML='<div class="guide-line v" style="left:33.333%"></div><div class="guide-line v" style="left:66.667%"></div><div class="guide-line h" style="top:33.333%"></div><div class="guide-line h" style="top:66.667%"></div>';const ratio={landscape:16/9,square:1,portrait:3/4}[p.aspect];if(ratio){let w=innerWidth,h=w/ratio;if(h>innerHeight){h=innerHeight;w=h*ratio;}$('photo-frame').style.width=w+'px';$('photo-frame').style.height=h+'px';}}
async function capture(){try{const result=await scene.capture({labels:s.photo?.labels??s.prefs.labels!=='none',caption:s.photo?.caption??true,scale:Number(s.photo?.resolution||1),aspect:s.photo?.aspect||'screen'});if(s.capture)URL.revokeObjectURL(s.capture.url);s.capture={...result,url:URL.createObjectURL(result.blob)};openTool('capture');}catch{toast(L('A captura não pôde ser concluída. Tente uma resolução menor.','Capture could not be completed. Try a lower resolution.'));}}
function record(){if(s.recording){stopRecording();return;}if(!window.MediaRecorder||!scene.renderer?.domElement.captureStream){toast(L('Gravação indisponível neste navegador. A captura PNG permanece disponível.','Recording is unavailable in this browser. PNG capture remains available.'));return;}try{const stream=scene.renderer.domElement.captureStream(24),mime=['video/webm;codecs=vp9','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime)throw Error('mime');const recorder=new MediaRecorder(stream,{mimeType:mime}),chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());download(new Blob(chunks,{type:mime}),'observatory.webm');toast(L('Vídeo concluído: apenas a cena 3D, sem rótulos HTML ou som.','Video finished: 3D scene only, without HTML labels or sound.'));};recorder.onerror=()=>{toast(L('A gravação falhou; use PNG.','Recording failed; use PNG.'));stopRecording();};recorder.start();s.recording={recorder,stream,timer:setTimeout(stopRecording,15000)};renderPhoto();toast(L('Gravando por até 15 segundos.','Recording for up to 15 seconds.'));}catch{toast(L('Não foi possível iniciar a gravação. Use PNG.','Recording could not start. Use PNG.'));}}
function stopRecording(){if(!s.recording)return;clearTimeout(s.recording.timer);if(s.recording.recorder.state!=='inactive')s.recording.recorder.stop();s.recording=null;renderPhoto();}
function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function jsonDownload(value,filename){download(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),filename);}
function csvDownload(rows,filename){const escapeCell=value=>{let str=String(value??'');if(/^[=+@]/.test(str))str="'"+str;return '"'+str.replace(/"/g,'""')+'"';};download(new Blob(['\ufeff'+rows.map(row=>row.map(escapeCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),filename);}
function saveCollection(key,item){if(s.data[key].length>=200){toast(L('Limite de 200 registros. Exporte e remova alguns para continuar.','Limit of 200 entries. Export and remove some to continue.'));return false;}s.data[key].push(item);return save();}
const entry=(title)=>({id:crypto.randomUUID(),title:title.slice(0,100),body:s.selected,time:s.clock.time});
function saveView(){const title=s.toolData.viewTitle.trim()||`${name(byId[s.selected])} · ${dateLabel(s.clock.time)}`;const view=s.toolSaved?.view||scene.snapshot();if(saveCollection('viewpoints',{...entry(title),view,dateMode:s.toolData.viewDateMode}))toast(L('Vista guardada neste navegador.','View saved in this browser.'));if(s.tool==='collections')renderDialog(true);}
function saveBookmark(){if(saveCollection('bookmarks',{...entry(`${name(byId[s.selected])} · ${dateLabel(s.clock.time)}`),scale:s.prefs.scale}))toast(L('Data guardada.','Date saved.'));if(s.tool==='collections'||s.tool==='time')renderDialog(true);}
function errorMessage(text){const el=$('tool-error');if(el)el.innerHTML=notice(text,'error');else toast(text);}
function releaseObservation(){if(!s.observation)return;s.clock.speed=s.observation.oldSpeed;s.clock.direction=s.observation.oldDirection;s.observation=null;}

async function act(action,value=''){
  try{
    // Explicit time/navigation commands take ownership from the one-orbit demonstration.
    if(s.observation&&['play','reverse','step-day','step-custom','speed-preset','apply-rate','apply-date','now','reset-simulation','observe-orbit','bookmark-prev','bookmark-next','collection-open','mission-visit','import-confirm','start-tour','start-activity','activity-sequence'].includes(action))releaseObservation();
    switch(action){
      case 'open':openTool(value);break;
      case 'tools':case 'learn':case 'help':case 'settings':openTool(action);break;
      case 'explore':if(s.tool)closeTool();break;
      case 'close-tool':closeTool();break;case 'tool-back':toolBack();break;
      case 'select':selectBody(value);break;
      case 'focus-object':if(s.tool)closeTool();selectBody(value,true);break;
      case 'focus':scene.focus(s.selected);s.welcome=false;renderHero();break;
      case 'follow':scene.focus(s.selected,'follow');s.welcome=false;renderHero();break;
      case 'free':if(s.tool)closeTool();scene.free();break;
      case 'system':if(s.tool)closeTool();scene.focus(value||s.selected,'system');s.selected=value||s.selected;s.inspectorOpen=true;s.inspectorTab='system';renderAll();break;
      case 'tidal':s.tidal=!s.tidal;renderInspector();toast(L('Traço ciano: direção do primário. Orientação idealizada, sem librações.','Cyan line: parent direction. Idealized orientation without libration.'));break;
      case 'reset-view':if(s.tour)pauseTour();scene.overview();renderStatus();break;
      case 'camera-menu':openTool('camera');break;
      case 'camera-preset':if(s.tool)closeTool();if(['top','low','overview'].includes(value))scene.overview(false,value);else scene.focus(s.selected,'focus',value);break;
      case 'camera-pan':{const [x,y]=value.split(',').map(Number);if(s.tool)closeTool();scene.pan(x,y);break;}
      case 'view-history':if(s.tool)closeTool();scene.historyMove(Number(value));break;
      case 'zoom':scene.zoom(Number(value));break;
      case 'nav-toggle':s.navOpen=!s.navOpen;if(s.navOpen)s.inspectorOpen=false;renderNavigator();renderInspector();updateInsets();break;
      case 'nav-filter':s.navFilter=value;renderNavigator();break;
      case 'inspector-close':s.inspectorOpen=false;renderInspector();updateInsets();break;
      case 'inspector-open':s.inspectorOpen=true;renderInspector();updateInsets();break;
      case 'inspector-tab':s.inspectorTab=value;if(value==='sources'&&s.selected==='moon')s.activitySeenSources=true;renderInspector();break;
      case 'clear-search':s.navQuery='';renderNavigator();break;
      case 'catalog-reset':s.toolData.commandQuery='';s.toolData.catalogFilter='all';renderDialog();break;
      case 'command':{const [a,v]=value.split('|');closeTool();await act(a,v);break;}
      case 'dismiss-welcome':s.welcome=false;s.data.onboarded=true;save();renderHero();toast(matchMedia('(pointer:coarse)').matches?L('Um dedo gira; dois dedos aproximam. Toque em um mundo para descobrir.','One finger orbits; two fingers zoom. Tap a world to discover.'):L('Arraste para orbitar. Role para aproximar. Selecione um mundo para descobrir.','Drag to orbit. Scroll to zoom. Select a world to discover.'));break;
      case 'restart-tutorial':closeTool();s.welcome=true;s.data.onboarded=false;save();renderHero();break;
      case 'play':s.clock.paused=!s.clock.paused;renderTimebar();break;
      case 'reverse':s.clock.direction*=-1;renderTimebar();break;
      case 'step-day':s.clock.step(Number(value)*DAY);scene.trailKey='';renderTimebar();break;
      case 'step-custom':s.clock.step(Number(value)*Number(s.toolData.stepSize));scene.trailKey='';renderDialog(true);renderTimebar();break;
      case 'speed-preset':s.clock.rate(Number(value)*s.clock.direction);s.toolData.customRate=s.clock.speed*s.clock.direction;renderTimebar();renderDialog(true);break;
      case 'apply-rate':s.clock.rate(s.toolData.customRate);renderTimebar();renderDialog(true);break;
      case 'apply-date':{const time=Date.parse(s.toolData.dateInput+'Z');s.clock.jump(time);s.clock.paused=true;scene.trailKey='';scene.pathScale=null;s.toolData.timelineAnchor=time;s.toolData.timelineOffset=0;renderTimebar();renderDialog(true);break;}
      case 'now':s.clock.jump(Date.now());s.toolData.dateInput=new Date(s.clock.time).toISOString().slice(0,16);scene.trailKey='';renderTimebar();renderDialog(true);break;
      case 'reset-simulation':s.clock.reset();scene.trailKey='';s.toolData.dateInput=new Date(s.clock.time).toISOString().slice(0,16);renderTimebar();if(s.tool)renderDialog(true);break;
      case 'observe-orbit':{const b=byId[s.selected];if(!b.period)break;const seconds=b.period*DAY;if(s.clock.time+seconds*1000>MAX_DATE){errorMessage(L('A órbita ultrapassa 2050. Escolha uma data anterior.','The orbit exceeds 2050. Choose an earlier date.'));break;}if(s.tool)closeTool();s.observation={target:s.selected,end:s.clock.time+seconds*1000,oldSpeed:s.clock.speed,oldDirection:s.clock.direction};s.clock.speed=Math.min(31557600,seconds/18);s.clock.direction=1;s.clock.paused=false;scene.focus(s.selected,'follow');s.prefs.trails=true;renderAll();toast(L('Observando uma órbita. Outros corpos mantêm seus próprios períodos.','Observing one orbit. Other bodies retain their own periods.'));break;}
      case 'labels':s.prefs.labels=s.prefs.labels==='none'?'major':'none';preferences();renderViewControls();break;
      case 'orbits':s.prefs.orbits=s.prefs.orbits==='none'?'all':'none';preferences();break;
      case 'clear-trails':s.prefs.trails=false;scene.trailKey='';preferences();renderDialog(true);break;
      case 'toggle-scale':s.prefs.scale=s.prefs.scale==='explore'?'relative':'explore';scene.setScale();preferences();renderTimebar();toast(s.prefs.scale==='relative'?L('Raios e distâncias agora compartilham uma escala real. Planetas ficam minúsculos: use marcadores e Focalizar.','Radii and distances now share one true scale. Planets become tiny: use markers and Focus.'):L('Escala de exploração: distâncias comprimidas e raios ampliados.','Exploration scale: compressed distances and enlarged radii.'));break;
      case 'favorite':{const id=s.selected,index=s.data.favorites.indexOf(id);if(index<0)s.data.favorites.push(id);else s.data.favorites.splice(index,1);save();renderInspector();renderNavigator();break;}
      case 'compare-selected':s.toolData.compare={ids:s.selected==='earth'?['earth','mars']:['earth',s.selected],ref:'earth'};openTool('compare');break;
      case 'compare-pair':s.toolData.compare.ids=value.split(',');s.toolData.compare.ref=s.toolData.compare.ids[0];renderDialog(true);break;
      case 'compare-left':{const ids=s.toolData.compare.ids,i=ids.indexOf(value);if(i>0)[ids[i-1],ids[i]]=[ids[i],ids[i-1]];renderDialog(true);break;}
      case 'compare-remove':{const d=s.toolData.compare;if(d.ids.length>2)d.ids=d.ids.filter(id=>id!==value);if(!d.ids.includes(d.ref))d.ref=d.ids[0];renderDialog(true);break;}
      case 'compare-swap':s.toolData.compare.ids.reverse();renderDialog(true);break;
      case 'export-comparison':exportComparison();break;
      case 'compare-image':exportComparisonImage();break;
      case 'scale-view':s.toolData.scale.view=value;if(value==='true')s.toolData.scale.axis='linear';renderDialog(true);break;
      case 'measure-selected':s.measurement={...initialLabs().measure,a:s.selected,b:s.selected==='sun'?'earth':'sun',time:s.clock.time};openTool('measure');break;
      case 'measure-swap':[s.measurement.a,s.measurement.b]=[s.measurement.b,s.measurement.a];renderDialog(true);break;
      case 'measure-freeze':s.measurement.frozen=!s.measurement.frozen;s.measurement.time=s.clock.time;renderDialog(true);break;
      case 'measure-save':s.measureHistory.unshift(distanceAt(s.measurement.a,s.measurement.b,s.measurement.frozen?s.measurement.time:s.clock.time));s.measureHistory=s.measureHistory.slice(0,30);renderDialog(true);break;
      case 'measure-scene':closeTool();s.measurePick=1;renderInspector();renderStatus();toast(L('Escolha o primeiro extremo na cena ou no catálogo.','Choose the first endpoint in the scene or catalog.'));break;
      case 'light-pulse':scene.pulseStart=performance.now();s.toolData.pulseStart=scene.pulseStart;toast(L('Pulso ilustrativo: viagem apresentada em 5 segundos.','Illustrative pulse: journey shown in 5 seconds.'));break;
      case 'export-measurements':csvDownload([[L('Data UTC','UTC date'),L('Origem','Origin'),L('Destino','Destination'),'km',L('UA','AU'),L('Luz: segundos de ida','Light: one-way seconds')],...s.measureHistory.map(m=>[new Date(m.time).toISOString(),name(byId[m.a]),name(byId[m.b]),m.km,m.au,m.seconds])],'measurements.csv');break;
      case 'season-preset':s.toolData.seasons.phase=Number(value);renderDialog(true);break;
      case 'moon-preset':s.toolData.moon.angle=['new','solar'].includes(value)?0:180;s.toolData.moon.eclipse=['solar','lunar'].includes(value)?value:'none';renderDialog(true);break;
      case 'moon-step':s.toolData.moon.angle=(s.toolData.moon.angle+45)%360;s.toolData.moon.eclipse='none';renderDialog(true);break;
      case 'kepler-preset':{const d=s.toolData.kepler;if(value==='circle')d.e=0;if(value==='ellipse')d.e=.6;if(value==='double')d.a=clamp(d.a*2,.1,10);d.phase=0;renderDialog(true);break;}
      case 'kepler-run':s.toolData.kepler.running=!s.toolData.kepler.running;renderDialog(true);break;
      case 'kepler-predict':s.toolData.kepler.prediction=L('Preveja antes de executar: aumentar o semieixo aumenta o período? Alterar a massa de teste muda a trajetória? Confira os valores e pressione Executar.','Predict before running: does increasing the semi-major axis increase the period? Does changing test mass change the trajectory? Inspect values and press Run.');renderDialog(true);break;
      case 'kepler-baseline':{const d=s.toolData.kepler,r=orbitExperiment(d.mass,d.a,d.e),baseline=orbitExperiment(1,1,0);d.prediction=`${L('Período / referência','Period / baseline')}: ${fmt(r.period/baseline.period,3)}×. ${L('Referência: 1 massa solar, 1 UA, círculo.','Baseline: 1 solar mass, 1 AU, circle.')}`;renderDialog(true);break;}
      case 'save-experiment':{const d=s.toolData.kepler;if(saveCollection('experiments',{...entry(L('Órbita hipotética','Hypothetical orbit')),params:{mass:d.mass,a:d.a,e:d.e,testMass:d.testMass}}))toast(L('Experimento guardado.','Experiment saved.'));break;}
      case 'export-experiment':jsonDownload({version:1,label:L('EXPERIMENTO HIPOTÉTICO','HYPOTHETICAL EXPERIMENT'),model:'Bound two-body Kepler orbit; negligible test mass; SI internally',parameters:{massSolar:s.toolData.kepler.mass,semiMajorAxisAU:s.toolData.kepler.a,eccentricity:s.toolData.kepler.e,testMassKg:s.toolData.kepler.testMass},results:orbitExperiment(s.toolData.kepler.mass,s.toolData.kepler.a,s.toolData.kepler.e)},'hypothetical-orbit.json');break;
      case 'lab-reset':{const fresh=initialLabs();if(s.tool in fresh)s.toolData[s.tool]=fresh[s.tool];if(s.tool==='gravity'){s.toolData.gravityBody='moon';s.toolData.personMass=70;}renderDialog(true);break;}
      case 'outer-step':s.toolData.outer.step=clamp(s.toolData.outer.step+Number(value),0,4);renderDialog(true);break;
      case 'apply-frame':s.prefs.frame=s.toolData.frameBody;preferences();renderStatus();toast(L('Referencial atualizado no mapa; o estado físico foi preservado.','Map frame updated; physical state was preserved.'));break;
      case 'mission-visit':{const m=missions.find(x=>x.id===value);closeTool();s.clock.jump(Date.parse(m.event+'T12:00:00Z'));s.clock.paused=true;selectBody(m.body,true);renderTimebar();toast(L('Marco histórico; posição planetária aproximada, sem trajetória da sonda.','Historical milestone; approximate planetary position, without spacecraft trajectory.'));break;}
      case 'article':s.toolData.article=value;openTool('article');break;
      case 'preset':applyPreset(value);break;
      case 'clean-background':s.prefs.background=0;preferences();renderDialog(true);break;
      case 'reset-settings':s.prefs={...defaults,language:s.prefs.language};preferences();scene.setScale();renderAll();break;
      case 'mute':s.prefs.sound=false;if(s.tour)s.tour.narration=false;window.speechSynthesis?.cancel();preferences();renderAll();break;
      case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast(L('Tela cheia indisponível; a vista sem distrações continua disponível.','Fullscreen unavailable; distraction-free view remains available.'));break;
      case 'zen':if(s.tool)closeTool();s.zen=true;updateStyles();break;case 'restore-ui':s.zen=false;updateStyles();break;
      case 'start-tour':startTour(value||'grand');break;
      case 'tour-toggle':s.tour.paused?resumeTour():pauseTour();break;
      case 'tour-prev':tourNext(-1);break;case 'tour-next':tourNext(1);break;
      case 'tour-jump':s.tour.index=Number(value);visitStop();break;
      case 'tour-stops':s.tour.stopList=!s.tour.stopList;renderTour();break;
      case 'tour-restart-stop':visitStop();break;
      case 'tour-inspect':pauseTour();s.inspectorOpen=true;renderInspector();updateInsets();toast(L('Passeio pausado. Você pode explorar e retomar na mesma parada.','Tour paused. Explore and resume at the same stop.'));break;
      case 'tour-exit':exitTour();break;
      case 'tour-narrate':if(!('speechSynthesis'in window)){toast(L('Narração indisponível; acompanhe pelo texto.','Narration unavailable; follow the text.'));break;}s.prefs.sound=true;s.tour.narration=!s.tour.narration;if(s.tour.narration)speakStop();else window.speechSynthesis.cancel();renderTour();break;
      case 'start-activity':startActivity(value);break;
      case 'activity-answer':s.activityAnswer=value;if(s.tool)renderDialog(true);else renderActivity();break;
      case 'activity-check':checkActivity();break;
      case 'activity-hint':s.activityHint=!s.activityHint;if(s.tool)renderDialog(true);else renderActivity();break;
      case 'activity-next':{const index=activities.findIndex(a=>a.id===s.activity);if(index<activities.length-1)startActivity(activities[index+1].id);else{exitActivity();openTool('learn');}break;}
      case 'activity-sequence':startActivity(s.data.progress.activity||activities.find(a=>!s.data.progress.activities.includes(a.id))?.id||activities[0].id);break;
      case 'activity-inspect':s.inspectorOpen=true;s.activityCollapsed=true;renderInspector();renderActivity();updateInsets();break;
      case 'activity-resume':s.activityCollapsed=false;renderActivity();break;
      case 'activity-exit':exitActivity();break;
      case 'photo':enterPhoto();break;case 'photo-exit':exitPhoto();break;case 'capture':await capture();break;case 'record':record();break;
      case 'photo-preset':s.selected=value;scene.focus(value,'focus',value==='saturn'?'default':'terminator');renderPhoto();break;
      case 'save-viewpoint':saveView();break;case 'save-bookmark':saveBookmark();break;
      case 'bookmark-prev':case 'bookmark-next':{const all=[...s.data.bookmarks].sort((a,b)=>a.time-b.time),item=action==='bookmark-next'?all.find(x=>x.time>s.clock.time)||all[0]:all.reverse().find(x=>x.time<s.clock.time)||all[0];if(item){s.clock.jump(item.time);s.clock.paused=true;selectBody(item.body);s.toolData.dateInput=new Date(item.time).toISOString().slice(0,16);if(s.tool)renderDialog(true);renderTimebar();}else toast(L('Nenhuma data foi guardada ainda.','No dates have been saved yet.'));break;}
      case 'collection-tab':s.toolData.collectionTab=value;s.toolData.collectionQuery='';renderDialog();break;
      case 'save-note':{const d=s.toolData;if(!d.noteTitle.trim()||!d.noteText.trim()){errorMessage(L('Escreva um título e uma observação antes de guardar.','Enter a title and observation before saving.'));break;}let ok;if(d.editNote){const n=s.data.notes.find(n=>n.id===d.editNote);n.title=d.noteTitle.trim();n.text=d.noteText;ok=save();}else ok=saveCollection('notes',{...entry(d.noteTitle.trim()),text:d.noteText});if(ok){d.noteTitle='';d.noteText='';d.editNote=null;toast(L('Anotação guardada.','Note saved.'));}renderDialog(true);break;}
      case 'note-edit':{const n=s.data.notes.find(n=>n.id===value);s.toolData.noteTitle=n.title;s.toolData.noteText=n.text;s.toolData.editNote=n.id;renderDialog();break;}
      case 'cancel-note-edit':s.toolData.editNote=null;s.toolData.noteTitle='';s.toolData.noteText='';renderDialog();break;
      case 'collection-open':{const tab=s.toolData.collectionTab;if(tab==='favorites'){closeTool();selectBody(value,true);break;}const item=s.data[tab].find(x=>x.id===value);if(tab==='experiments'){s.toolData.kepler={...initialLabs().kepler,...item.params};openTool('kepler');}else{closeTool();s.selected=item.body;s.clock.paused=true;if(tab==='viewpoints'){scene.restore(item.view,item.dateMode!=='current');}else{s.clock.jump(item.time);scene.focus(item.body);}renderAll();}break;}
      case 'collection-rename':{const tab=s.toolData.collectionTab,item=s.data[tab].find(x=>x.id===value),title=prompt(L('Novo nome (até 100 caracteres)','New name (up to 100 characters)'),item.title);if(title?.trim()){item.title=title.trim().slice(0,100);save();renderDialog(true);}break;}
      case 'collection-duplicate':{const tab=s.toolData.collectionTab,item=s.data[tab].find(x=>x.id===value);saveCollection(tab,{...structuredClone(item),id:crypto.randomUUID(),title:(item.title+L(' · cópia',' · copy')).slice(0,100)});renderDialog(true);break;}
      case 'collection-delete':{const tab=s.toolData.collectionTab,item=tab==='favorites'?value:s.data[tab].find(x=>x.id===value);if(confirm(`${L('Excluir somente este registro?','Delete only this entry?')} ${tab==='favorites'?name(byId[value]):item.title}`)){s.data[tab]=s.data[tab].filter(x=>tab==='favorites'?x!==value:x.id!==value);save();renderDialog(true);renderNavigator();}break;}
      case 'clear-collection':{const tab=s.toolData.collectionTab;if(confirm(`${L('Limpar apenas esta coleção?','Clear only this collection?')} ${s.data[tab].length} ${L('registros serão excluídos.','entries will be deleted.')}`)){s.data[tab]=[];save();renderDialog(true);}break;}
      case 'export-data':jsonDownload(s.data,'observatory-collections.json');break;
      case 'share':s.shareData=sceneFile(scene.snapshot());openTool('share');break;
      case 'export-scene':jsonDownload(s.shareData,'observatory-scene.json');break;
      case 'copy-scene':try{await navigator.clipboard.writeText(JSON.stringify(s.shareData));toast(L('Configuração copiada.','Configuration copied.'));}catch{toast(L('A cópia automática foi bloqueada. Selecione o texto ou baixe o arquivo.','Automatic copying was blocked. Select the text or download the file.'));}break;
      case 'import-cancel':s.importData=null;toolBack();break;
      case 'import-confirm':{const data=s.importData;if(data.kind==='observatory-scene'){closeTool();scene.restore(data.view,true);s.selected=data.view.target;s.clock.paused=true;renderAll();}else{const merged=structuredClone(s.data);for(const k of ['favorites','viewpoints','bookmarks','notes','experiments']){merged[k]=k==='favorites'?[...new Set([...merged[k],...data[k]])]:[...merged[k],...data[k].filter(x=>!merged[k].some(y=>y.id===x.id))];}for(const key of ['visited','activities','tours'])merged.progress[key]=[...new Set([...merged.progress[key],...data.progress[key]])];merged.progress.activity=merged.progress.activity||data.progress.activity;merged.preferences={...data.preferences};s.data=validateData(merged);s.prefs={...s.data.preferences};save();s.importData=null;closeTool();openTool('collections');toast(L('Conteúdo validado mesclado.','Validated content merged.'));}break;}
      case 'retry-assets':await scene.retryAssets();renderInspector();s.sceneDiagnostics=scene.diagnostics();renderDialog(true);toast(L('Nova tentativa concluída. Texturas indisponíveis mantêm a aparência ilustrativa.','Retry finished. Unavailable textures retain their illustrative appearance.'));break;
      case 'retry-renderer':save();location.reload();break;
      default:console.warn('Unhandled action',action);
    }
  }catch(error){console.error('Action failed:',action,error);errorMessage(['apply-rate','apply-date','apply-rate'].includes(action)?L('Valor inválido. Use uma data de 1800 a 2050 e uma taxa finita de até ±31.557.600×.','Invalid value. Use a date from 1800 to 2050 and a finite rate up to ±31,557,600×.'):L('Não foi possível concluir esta ação. Sua sessão permanece disponível.','This action could not be completed. Your session remains available.'));}
}

function applyPreset(id){const preset={cinema:{quality:'high',labels:'selected',orbits:'none',background:.5,presentation:'enhanced',grid:false},classroom:{quality:'medium',labels:'major',orbits:'all',background:.25,highContrast:true,grid:true},study:{quality:'high',labels:'system',orbits:'system',grid:true,axes:true,presentation:'natural'},low:{quality:'low',background:.15,labels:'major',orbits:'selected',grid:false,axes:false,trails:false}}[id];Object.assign(s.prefs,preset);preferences();renderAll();toast(L('Preferências aplicadas. Todos os controles continuam ajustáveis.','Preferences applied. Every setting remains adjustable.'));}
function exportComparison(){const d=s.toolData.compare,unit=s.prefs.units,factor=unit==='mi'?.621371:1;csvDownload([[L('Corpo','Body'),L(`Diâmetro médio (${unit})`,`Mean diameter (${unit})`),L('Massa (kg)','Mass (kg)'),L('Gravidade de referência (m/s²)','Reference gravity (m/s²)'),L('Densidade (g/cm³)','Density (g/cm³)'),L('Rotação sideral (dias)','Sidereal rotation (days)'),L('Período orbital (dias)','Orbital period (days)'),L('Primário','Primary'),L('Razão de diâmetro / referência','Diameter ratio / reference'),name(byId[d.ref]),L('Fontes consultadas','Sources accessed')],...d.ids.map(id=>{const b=byId[id];return [name(b),b.radius*2*factor,b.mass,b.gravity,b.density,b.rotation,b.period,name(byId[b.parent]),b.radius/byId[d.ref].radius,'JPL / approximate educational model',DATA_DATE];})],'world-comparison.csv');}
function exportComparisonImage(){const unit=s.prefs.units,factor=unit==='mi'?.621371:1;const d=s.toolData.compare,list=d.ids.map(id=>byId[id]),max=Math.max(...list.map(b=>b.radius));const source=`<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="470" viewBox="0 0 1000 470"><rect width="1000" height="470" fill="#0b121c"/><text x="40" y="45" fill="#dce9ee" font-size="22" font-family="sans-serif">${L('Diâmetros médios · escala linear','Mean diameters · linear scale')}</text>${list.map((b,i)=>`<circle cx="${(i+.5)*1000/list.length}" cy="${305-b.radius/max*100}" r="${b.radius/max*100}" fill="${b.color}"/><text x="${(i+.5)*1000/list.length}" y="350" text-anchor="middle" fill="#e2ebef" font-family="sans-serif">${e(name(b))} · ${fmt(b.radius*2*factor,1)} ${unit}</text>`).join('')}<text x="40" y="406" fill="#a1b4c0" font-family="sans-serif">${L('Referência','Reference')}: ${e(name(byId[d.ref]))} · ${L('Uma única escala de diâmetro','One common diameter scale')}</text><text x="40" y="440" fill="#a1b4c0" font-family="sans-serif">NASA / JPL · ${DATA_DATE} · ${L('Valores de referência aproximados','Approximate reference values')}</text></svg>`;download(new Blob([source],{type:'image/svg+xml'}),'world-comparison.svg');}

async function fieldChange(el,eventType){const key=el.dataset.field;if(!key)return;let value=el.type==='checkbox'?el.checked:el.value;if(key==='customRate'){s.toolData.customRate=el.value;return;}const numeric=el.type==='range'||el.type==='number';if(numeric){if(el.value.trim()===''||!Number.isFinite(Number(value)))return;value=Number(value);if(el.min!==''&&value<Number(el.min)||el.max!==''&&value>Number(el.max))return;}
  if(key==='importFile'){if(eventType!=='change')return;const file=el.files[0];if(!file)return;if(file.size>2_000_000){toast(L('Arquivo maior que 2 MB.','File exceeds 2 MB.'));return;}try{const raw=JSON.parse(await file.text());if(raw.kind==='observatory-scene'){if(raw.version!==1||!validateView(raw.view))throw Error('schema');s.importData=raw;}else s.importData=validateData(raw);openTool('import');}catch{toast(L('Arquivo recusado: formato, versão, valores ou identificadores inválidos. Nada foi importado.','File rejected: invalid format, version, values or identifiers. Nothing was imported.'));}return;}
  if(key==='navQuery'){s.navQuery=value;renderNavigator();return;}
  if(key==='speedLog'){releaseObservation();s.clock.speed=Math.min(31557600,Math.round(10**value));$('speed-phrase').textContent=speedPhrase();$('speed-multiplier').textContent=`${s.clock.direction<0?'−':''}${fmt(s.clock.speed)}×`;return;}
  if(key==='tour.auto'){s.tour.auto=value;renderTour();return;}
  if(key==='activityAnswer'){s.activityAnswer=value;return;}
  if(key.startsWith('pref.')){const k=key.slice(5);s.prefs[k]=value;if(s.tour&&['labels','orbits'].includes(k))s.tour.saved[k]=value;if(!s.photo)preferences();if(k==='scale')scene.setScale();if(k==='reducedMotion'&&reduced()){s.clock.paused=true;scene.transition=null;}if(k==='language'){window.speechSynthesis?.cancel();$('toast').hidden=true;$('dialog-toast').hidden=true;renderAll();}else{updateStyles();renderTimebar();renderInspector();if(s.tool)renderDialog(true);if(s.photo)renderPhoto();}return;}
  if(key.startsWith('photo.')){const k=key.slice(6);if(k==='fov'){scene.camera.fov=value;scene.camera.updateProjectionMatrix();}else s.photo[k]=value;if(k==='freeze')s.clock.paused=value;if(k==='labels')s.prefs.labels=value?'major':'none';if(k==='orbits')s.prefs.orbits=value?'all':'none';renderPhoto();return;}
  if(key==='compareAdd'){if(value&&s.toolData.compare.ids.length<4&&!s.toolData.compare.ids.includes(value))s.toolData.compare.ids.push(value);renderDialog(true);return;}
  if(key==='compareRef'){s.toolData.compare.ref=value;renderDialog(true);return;}
  if(key==='timeline'){releaseObservation();s.toolData.timelineOffset=value;s.clock.jump(clamp(s.toolData.timelineAnchor+value*DAY*1000,MIN_DATE,MAX_DATE));s.clock.paused=true;s.toolData.dateInput=new Date(s.clock.time).toISOString().slice(0,16);scene.trailKey='';renderTimebar();renderDialog(true);return;}
  if(key.startsWith('measure.')){s.measurement[key.slice(8)]=value;renderDialog(true);return;}
  const parts=key.split('.');if(parts.length===2){const [section,k]=parts;s.toolData[section][k]=value;if(section==='moon'&&k==='angle')s.toolData.moon.eclipse='none';renderDialog(true);return;}
  s.toolData[key]=value;
  if(['noteTitle','noteText','viewTitle','dateInput','customRate','viewDateMode','stepSize'].includes(key))return;
  if(key==='timelineSpan'){s.toolData.timelineSpan=Number(value);s.toolData.timelineAnchor=s.clock.time;s.toolData.timelineOffset=0;}
  if(s.tool)renderDialog(true);
}

document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target&&!target.disabled)void act(target.dataset.action,target.dataset.value||'');});
document.addEventListener('input',event=>{if(event.target.matches('input:not([type=checkbox]):not([type=file]),textarea'))void fieldChange(event.target,'input');});
document.addEventListener('change',event=>{if(event.target.matches('input[type=range]')&&dialog.open)renderDialog(true,true);if(event.target.matches('select,input[type=checkbox],input[type=file]'))void fieldChange(event.target,'change');});
dialog.addEventListener('cancel',event=>{event.preventDefault();if(s.toolStack.length)toolBack();else closeTool();});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeTool();}});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&!dialog.open){if(s.photo)exitPhoto();else if(s.navOpen){s.navOpen=false;renderNavigator();}else if(s.zen){s.zen=false;updateStyles();}else if(s.activity)exitActivity();else if(s.tour)exitTour();else if(s.measurePick){s.measurePick=0;renderAll();}else{s.inspectorOpen=false;renderInspector();updateInsets();}return;}
  const target=event.target;if(target.matches('input[type=search]')&&['ArrowDown','ArrowUp','Enter'].includes(event.key)){const area=dialog.open?$('dialog-content'):$('navigator'),results=[...area.querySelectorAll('button[data-action=select]')];if(event.key==='Enter'){if(results[0]){event.preventDefault();void act('select',results[0].dataset.value);}}else if(results.length){event.preventDefault();results[event.key==='ArrowDown'?0:results.length-1].focus();}return;}
  if(target.matches('.body-row')&&['ArrowDown','ArrowUp'].includes(event.key)){const rows=[...target.parentElement.querySelectorAll('.body-row')],i=rows.indexOf(target);event.preventDefault();rows[(i+(event.key==='ArrowDown'?1:-1)+rows.length)%rows.length].focus();return;}
  if(event.repeat||event.ctrlKey||event.metaKey||event.altKey||dialog.open||target.matches('input,textarea,select,button')||target.isContentEditable)return;
  const shortcuts={' ':'play',r:'reset-view',o:'orbits',l:'labels',f:'focus',g:'follow',c:'compare-selected',p:'photo',h:'zen'};const action=shortcuts[event.key.toLowerCase()];if(action){event.preventDefault();void act(action);}if(event.key==='/'){event.preventDefault();s.toolData.commandQuery='';openTool('commands');}
});
document.addEventListener('visibilitychange',()=>{s.clock.hidden=document.hidden;lastTick=performance.now();if(document.hidden){window.speechSynthesis?.cancel();stopRecording();}});
window.addEventListener('resize',()=>{updateInsets();renderPhoto();});
function updateLive(now){$('date-display').textContent=dateLabel(s.clock.time);$('clock-state').textContent=s.clock.paused?L('Pausada','Paused'):L('Em movimento','In motion');const el=document.querySelector('[data-live=sun-distance]');if(el){el.textContent=`${fmt(length(positionsAt(s.clock.time).positions[s.selected]))} km`;const parent=document.querySelector('[data-live=parent-distance]');if(parent)parent.textContent=`${fmt(distanceAt(s.selected,byId[s.selected].parent,s.clock.time).km)} km`;}
  if(s.tool==='measure'&&s.measurement){const m=s.measurement,time=m.frozen?m.time:s.clock.time,r=distanceAt(m.a,m.b,time);for(const [key,val]of [['distance-km',fmt(r.km)],['distance-au',fmt(r.au,6)],['distance-light',fmt(r.seconds,2)],['measure-date',new Date(time).toISOString()]]){const el=document.querySelector(`[data-live=${key}]`);if(el)el.textContent=val;}const angle=angularSeparation(m.a,m.b,m.observer,time),el=document.querySelector('[data-live=angle]');if(el)el.textContent=angle===null?L('Indefinida','Undefined'):fmt(angle,3)+'°';}
  renderMap();if(s.tool==='settings'&&$('diagnostics'))$('diagnostics').textContent=JSON.stringify(scene.diagnostics(),null,2);
}
function renderMap(){if(innerWidth<=650||s.photo||s.zen)return;const physical=positionsAt(s.clock.time).positions,origin=s.prefs.frame==='selected'?s.selected:s.prefs.frame,base=physical[origin]||physical.sun;const dots=[byId.sun,...planets].map(b=>{const v=sub(physical[b.id],base),r=length(v),scale=r?Math.log1p(r/AU)/Math.log(32)*42/r:0;return `<circle cx="${60+v[0]*scale}" cy="${57-v[1]*scale}" r="${b.id===s.selected?3:1.7}" fill="${b.color}" data-action="focus-object" data-value="${b.id}"/><title>${name(b)}</title>`;}).join('');const angle=scene.camera?Math.atan2(scene.camera.position.z,scene.camera.position.x):0;$('orientation').innerHTML=`<svg viewBox="0 0 120 120" aria-label="${L('Mapa de orientação, distâncias logarítmicas','Orientation map, logarithmic distances')}" role="img"><circle cx="60" cy="57" r="44" fill="#111b2444" stroke="#a9c3d129"/><circle cx="60" cy="57" r="29" fill="none" stroke="#a9c3d11c"/><circle cx="60" cy="57" r="15" fill="none" stroke="#a9c3d11c"/><path d="M60 9V15M108 57h-6M60 99v6M12 57h6" stroke="#89a4b470"/>${dots}<path d="M57 108 60 101 63 108" transform="rotate(${angle*180/Math.PI},60,57)" stroke="#c4d5df" fill="none"/><text x="60" y="8" fill="#8fa4b3" text-anchor="middle" font-size="7">+Y</text></svg><div class="map-caption">${L('ORIENTAÇÃO · LOG','ORIENTATION · LOG')}</div>`;}
let lastSceneKey='';
function loop(now){const dt=(now-lastTick)/1000;lastTick=now;if(!document.hidden){s.clock.advance(dt);const sceneKey=JSON.stringify([s.clock.time,s.prefs,s.selected,s.measurement,s.tidal,s.tool,innerWidth,innerHeight,scene.lost]);if(!s.tool||s.photo||scene.transition||scene.pulseStart||sceneKey!==lastSceneKey){scene.tick(dt,now);lastSceneKey=sceneKey;}else if(!scene.failed)scene.measurePerformance(dt,now);if(s.clock.boundary&&!s.boundaryAnnounced){s.boundaryAnnounced=true;toast(L('Limite de validade atingido. Simulação pausada.','Validity boundary reached. Simulation paused.'));renderTimebar();}if(!s.clock.boundary)s.boundaryAnnounced=false;
    if(s.tour&&!s.tour.paused&&!s.tool&&!s.photo){s.tour.elapsed+=Math.min(dt,.25);if(s.tour.auto&&s.tour.elapsed>Math.max(10,stopText().length/13))tourNext(1);}
    if(s.observation&&s.clock.time>=s.observation.end){s.clock.time=s.observation.end;s.clock.paused=true;s.clock.speed=s.observation.oldSpeed;s.clock.direction=s.observation.oldDirection;s.observation=null;renderTimebar();toast(L('Uma órbita concluída. O relógio foi pausado no instante final.','One orbit completed. The clock paused at the final instant.'));}
    if(s.tool==='kepler'){const d=s.toolData.kepler;if(d.running)d.phase=(d.phase+Math.min(dt,.1)*TAU/12)%TAU;const p=orbitPoint(210,d.e,0,0,0,d.phase),orb=$('kepler-orbiter');if(orb){orb.setAttribute('cx',310+210*d.e+p[0]);orb.setAttribute('cy',175+p[1]*.53);}}
    if(s.tool==='measure'&&s.toolData.pulseStart){const el=$('tool-light-pulse'),p=clamp((now-s.toolData.pulseStart)/5000,0,1);if(el)el.setAttribute('cx',100+420*p);if(p===1)s.toolData.pulseStart=0;}
    if(now-lastUI>350){lastUI=now;updateLive(now);}}
  requestAnimationFrame(loop);
}
renderAll();requestAnimationFrame(loop);
if(loaded.error)toast(L('Preferências locais não puderam ser restauradas. Uma sessão limpa está pronta para explorar.','Local preferences could not be restored. A fresh session is ready to explore.'));
if(scene.failed)showRecovery('webgl');
// Public, read-only snapshots support reproducible diagnostics without exposing local notes.
window.observatory={snapshot:()=>({selected:s.selected,time:s.clock.time,speed:s.clock.speed,direction:s.clock.direction,paused:s.clock.paused,scale:s.prefs.scale,language:s.prefs.language,camera:scene.snapshot(),tool:s.tool,tour:s.tour?{id:s.tour.id,index:s.tour.index,paused:s.tour.paused}:null,activity:s.activity,lab:structuredClone({seasons:s.toolData.seasons,moon:s.toolData.moon,kepler:s.toolData.kepler}),measurement:s.measurement?{...s.measurement}:null,collections:Object.fromEntries(['favorites','viewpoints','bookmarks','notes','experiments'].map(k=>[k,s.data[k].length])),diagnostics:scene.diagnostics()}),ready:Promise.allSettled(scene.assetPromises||[])};
